/* The Readings Library, group carmina (GWG BLD 798). Written by build-readings.py; edit the data, then build again. */
(window.GGReadingsData = window.GGReadingsData || {})["carmina"] = [{"id":"carmina-rune-before-prayer","title":"Rune Before Prayer","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"prayer","occasion":["morning","daily"],"text":"I am bending my knee\nIn the eye of the Father who created me,\nIn the eye of the Son who purchased me,\nIn the eye of the Spirit who cleansed me,\nIn friendship and affection.\nThrough Thine own Anointed One, O God,\nBestow upon us fullness in our need,\nLove towards God,\nThe affection of God,\nThe smile of God,\nThe wisdom of God,\nThe grace of God,\nThe fear of God,\nAnd the will of God\nTo do on the world of the Three,\nAs angels and saints\nDo in heaven;\nEach shade and light,\nEach day and night,\nEach time in kindness,\nGive Thou us Thy Spirit.","note":"Said kneeling before the day's prayers, asking for the smile, the wisdom, and the grace of God.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1004.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-god-with-me-lying-down","title":"God With Me Lying Down","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"prayer","occasion":["evening","morning","daily"],"text":"God with me lying down,\nGod with me rising up,\nGod with me in each ray of light,\nNor I a ray of joy without Him,\nNor one ray without Him.\n\nChrist with me sleeping,\nChrist with me waking,\nChrist with me watching,\nEvery day and night,\nEach day and night.\n\nGod with me protecting,\nThe Lord with me directing,\nThe Spirit with me strengthening,\nFor ever and for evermore,\nEver and evermore, Amen.\nChief of chiefs, Amen.","note":"A short prayer for lying down at night and rising in the morning.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1005.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-invocation-graces","title":"From the Invocation of the Graces","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"blessing","occasion":["blessing","wedding","birth","celebration"],"text":"A shade art thou in the heat,\nA shelter art thou in the cold,\nEyes art thou to the blind,\nA staff art thou to the pilgrim,\nAn island art thou at sea,\nA fortress art thou on land,\nA well art thou in the desert,\nHealth art thou to the ailing.\n\nThou art the joy of all joyous things,\nThou art the light of the beam of the sun,\nThou art the door of the chief of hospitality,\nThou art the surpassing star of guidance,\nThou art the step of the deer of the hill,\nThou art the step of the steed of the plain,\nThou art the grace of the swan of swimming,\nThou art the loveliness of all lovely desires.\n\nThe lovely likeness of the Lord\nIs in thy pure face,\nThe loveliest likeness that\nWas upon earth.\n\nThe best hour of the day be thine,\nThe best day of the week be thine,\nThe best week of the year be thine,\nThe best year in the Son of God's domain be thine.","note":"A blessing spoken over a loved one, often a young woman setting out in life, naming the graces wished for her.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1006.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-general-supplication","title":"A General Supplication","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"prayer","occasion":["daily","comfort"],"text":"God, listen to my prayer,\nBend to me Thine ear,\nLet my supplications and my prayers\nAscend to Thee upwards,\nCome, Thou King of Glory,\nTo protect me down,\nThou King of life and mercy\nWith the aid of the Lamb.\nThou Son of Mary Virgin\nTo protect me with power,\nThou Son of the lovely Mary\nOf purest fairest beauty.","note":"A plain prayer asking God to bend near and listen.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1007.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-jesu-son-of-mary","title":"Jesu, Thou Son of Mary","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"litany","occasion":["daily","dying","peace"],"text":"Jesu, Thou Son of Mary,\nHave mercy upon us,\nAmen.\nJesu, Thou Son of Mary,\nMake peace with us,\nAmen.\nOh, with us and for us\nWhere we shall longest be,\nAmen.\nBe about the morning of our course,\nBe about the closing of our life,\nAmen.\nBe at the dawning of our life,\nAnd oh! at the dark'ning of our day,\nAmen.\nBe for us and with us,\nMerciful God of all,\nAmen.\nConsecrate us\nCondition and lot,\nThou King of kings,\nThou God of all,\nAmen.\nConsecrate us\nRights and means,\nThou King of kings,\nThou God of all,\nAmen.\n\nConsecrate us\nHeart and body,\nThou King of kings,\nThou God of all,\nAmen.\nEach heart and body,\nEach day to Thyself,\nEach night accordingly,\nThou King of kings,\nThou God of all,\nAmen.","note":"A litany asking Christ to be with us at the morning of our course and the closing of our life.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1009.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-holy-father-of-glory","title":"From Holy Father of Glory","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"prayer","occasion":["gratitude","funeral","hope"],"text":"Thanks be to Thee, Holy Father of Glory,\nFather kind, ever-loving, ever-powerful,\nBecause of all the abundance, favour, and deliverance\nThat Thou bestowest upon us in our need.\nWhatever providence befalls us as thy children,\nIn our portion, in our lot, in our path,\nGive to us with it the rich gifts of Thine hand\nAnd the joyous blessing of Thy mouth.\n\nIn the steep common path of our calling,\nBe it easy or uneasy to our flesh,\nBe it bright or dark for us to follow,\nThine own perfect guidance be upon us.\nBe Thou a shield to us from the wiles of the deceiver,\nFrom the arch-destroyer with his arrows pursuing us,\nAnd in each secret thought our minds get to weave,\nBe Thou Thyself on our helm and at our sheet.\n\nNow to the Father who created each creature,\nNow to the Son who paid ransom for His people,\nNow to the Holy Spirit, Comforter of might:\nShield and sain us from every wound;\nBe about the beginning and end of our race,\nBe giving us to sing in glory,\nIn peace, in rest, in reconciliation,\nWhere no tear shall be shed, where death comes no more.\nWhere no tear shall be shed, where death comes no more.","note":"A prayer of thanks that ends looking toward the place where no tear is shed; fitting at a funeral or a hard time.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1010.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-a-prayer-mary","title":"In My Deeds, in My Words","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian","catholic"],"denom":["scottish"],"type":"prayer","occasion":["daily","evening"],"text":"O God,\nIn my deeds,\nIn my words,\nIn my wishes,\nIn my reason,\nAnd in the fulfilling of my desires,\nIn my sleep,\nIn my dreams,\nIn my repose.\nIn my thoughts,\nIn my heart and soul always,\nMay the blessed Virgin Mary,\nAnd the promised Branch of Glory dwell,\nOh! in my heart and soul always,\nMay the blessed Virgin Mary,\nAnd the fragrant Branch of Glory dwell.","note":"A short prayer asking that the Virgin Mary and Christ dwell in every part of a life, waking and sleeping.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1011.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-king-of-the-moon","title":"From the Rune of the Muthairn","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"prayer","occasion":["nature","morning","gratitude"],"text":"Thou King of the moon,\nThou King of the sun,\nThou King of the planets,\nThou King of the stars,\nThou King of the globe,\nThou King of the sky,\nOh! lovely Thy countenance,\nThou beauteous Beam.","note":"A praise of God as King of the moon, the sun, the planets, and the stars.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1012.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-guiding-light","title":"The Guiding Light of Eternity","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian","all"],"denom":["scottish"],"type":"prayer","occasion":["morning","dying","hope"],"text":"O God, who broughtst me from the rest of last night\nUnto the joyous light of this day,\nBe Thou bringing me from the new light of this day\nUnto the guiding light of eternity.\nOh! from the new light of this day\nUnto the guiding light of eternity.","note":"A morning prayer that also suits the end of life: from the light of this day to the guiding light of eternity.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1014.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-prayer-for-grace","title":"A Prayer for Grace","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"prayer","occasion":["daily","forgiveness","peace"],"text":"I am bending my knee\nIn the eye of the Father who created me,\nIn the eye of the Son who died for me,\nIn the eye of the Spirit who cleansed me,\nIn love and desire.\n\nPour down upon us from heaven\nThe rich blessing of Thy forgiveness;\nThou who art uppermost in the City,\nBe Thou patient with us.\n\nGrant to us, Thou Saviour of Glory,\nThe fear of God, the love of God, and His affection,\nAnd the will of God to do on earth at all times\nAs angels and saints do in heaven;\nEach day and night give us Thy peace.\nEach day and night give us Thy peace.","note":"A kneeling prayer for forgiveness and for peace each day and night.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1015.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-jesu-ought-to-be-praised","title":"Jesu Who Ought to Be Praised","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"hymn","occasion":["nature","gratitude","healing"],"text":"It were as easy for Jesu\nTo renew the withered tree\nAs to wither the new\nWere it His will so to do.\nJesu! Jesu! Jesu!\nJesu! meet it were to praise Him.\n\nThere is no plant in the ground\nBut is full of His virtue,\nThere is no form in the strand\nBut is full of His blessing.\nJesu! Jesu! Jesu!\nJesu! meet it were to praise Him.\n\nThere is no life in the sea,\nThere is no creature in the river,\nThere is naught in the firmament,\nBut proclaims His goodness.\nJesu! Jesu! Jesu!\nJesu! meet it were to praise Him.\n\nThere is no bird on the wing,\nThere is no star in the sky,\nThere is nothing beneath the sun,\nBut proclaims His goodness.\nJesu! Jesu! Jesu!\nJesu! meet it were to praise Him.","note":"A song of praise for the goodness found in every plant, creature, bird, and star.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1017.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-rock-of-rocks","title":"The Rock of Rocks","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"blessing","occasion":["peace","blessing","home"],"text":"On the Rock of rocks,\nThe peace of Peter and Paul,\nOf James and John the beloved,\nAnd of the pure perfect Virgin,\nThe pure perfect Virgin.\n\nThe peace of the Father of joy,\nThe peace of the Christ of pasch,\nThe peace of the Spirit of grace,\nTo ourselves and to our children,\nOurselves and our children.","note":"A blessing of peace on ourselves and our children.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1018.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-lightener-of-stars","title":"The Lightener of the Stars","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"hymn","occasion":["nature","evening","gratitude"],"text":"Behold the Lightener of the stars\nOn the crests of the clouds,\nAnd the choralists of the sky\nLauding Him.\n\nComing down with acclaim\nFrom the Father above,\nHarp and lyre of song\nSounding to Him.\n\nChrist, Thou refuge of my love,\nWhy should not I raise Thy fame!\nAngels and saints melodious\nSinging to Thee.\n\nThou Son of the Mary of graces,\nOf exceeding white purity of beauty,\nJoy were it to me to be in the fields\nOf Thy riches.\n\nO Christ my beloved,\nO Christ of the Holy Blood,\nBy day and by night\nI praise Thee.","note":"A hymn of praise to Christ as the one who lights the stars.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1019.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-guardian-angel","title":"The Guardian Angel","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian","catholic"],"denom":["scottish"],"type":"prayer","occasion":["evening","dying","comfort"],"text":"Thou angel of God who hast charge of me\nFrom the dear Father of mercifulness,\nThe shepherding kind of the fold of the saints\nTo make round about me this night;\n\nDrive from me every temptation and danger,\nSurround me on the sea of unrighteousness,\nAnd in the narrows, crooks, and straits,\nKeep thou my coracle, keep it always.\n\nBe thou a bright flame before me,\nBe thou a guiding star above me,\nBe thou a smooth path below me,\nAnd be a kindly shepherd behind me,\nTo-day, to-night, and for ever.\n\nI am tired and I a stranger,\nLead thou me to the land of angels;\nFor me it is time to go home\nTo the court of Christ, to the peace of heaven.","note":"A night prayer to the guardian angel, whose last verse is often read at the end of life.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1021.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-desires","title":"Desires","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"prayer","occasion":["daily","gratitude","morning"],"text":"May I speak each day according to Thy justice,\nEach day may I show Thy chastening, O God;\nMay I speak each day according to Thy wisdom,\nEach day and night may I be at peace with Thee.\n\nEach day may I count the causes of Thy mercy,\nMay I each day give heed to Thy laws;\nEach day may I compose to Thee a song,\nMay I harp each day Thy praise, O God.\n\nMay I each day give love to Thee, Jesu,\nEach night may I do the same;\nEach day and night, dark and light,\nMay I laud Thy goodness to me, O God.","note":"A prayer of daily intention: to count the causes of God's mercy and to make a song each day.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1022.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-lustration","title":"From the Lustration","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"blessing","occasion":["morning","blessing","daily"],"text":"I am bathing my face\nIn the mild rays of the sun,\nAs Mary bathed Christ\nIn the rich milk of Egypt.\n\nSweetness be in my mouth,\nWisdom be in my speech,\nThe love the fair Mary gave her Son\nBe in the heart of all flesh for me.\n\nThe love of Christ in my breast,\nThe form of Christ protecting me,\nThere is not in sea nor on land\nThat can overcome the King of the Lord's Day.\n\nThe hand of Bride about my neck,\nThe hand of Mary about my breast,\nThe hand of Michael laving me,\nThe hand of Christ saving me.","note":"Said while washing the face in the morning, asking that love and wisdom go out into the day.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1026.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-god-guide-me","title":"God Guide Me","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"prayer","occasion":["daily","morning"],"text":"God guide me with Thy wisdom,\nGod chastise me with Thy justice,\nGod help me with Thy mercy,\nGod protect me with Thy strength.\n\nGod fill me with Thy fullness,\nGod shield me with Thy shade,\nGod fill me with Thy grace,\nFor the sake of Thine Anointed Son.\n\nJesu Christ of the seed of David,\nVisiting One of the Temple,\nSacrificial Lamb of the Garden,\nWho died for me.","note":"A short prayer for guidance, help, and protection.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1028.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-sleep-blessing","title":"From the Sleep Blessing","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"blessing","occasion":["evening","peace"],"text":"Be Thy right hand, O God, under my head,\nBe Thy light, O Spirit, over me shining.\nAnd be the cross of the nine angels over me down,\nFrom the crown of my head to the soles of my feet,\nFrom the crown of my head to the soles of my feet.\n\nBe the cross of Mary and of Michael over me in peace,\nBe my soul dwelling in truth, be my heart free of guile,\nBe my soul in peace with thee, Brightness of the mountains.\nValiant Michael, meet thou my soul,\nMorn and eve, day and night. May it be so.","note":"A bedtime blessing asking God's hand under the head and God's light shining over.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1029.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-come-i-this-day","title":"Come I This Day","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"prayer","occasion":["morning","daily"],"text":"Come I this day to the Father,\nCome I this day to the Son,\nCome I to the Holy Spirit powerful;\nCome I this day with God,\nCome I this day with Christ,\nCome I with the Spirit of kindly balm,\n\nGod, and Spirit, and Jesus,\nFrom the crown of my head\nTo the soles of my feet;\nCome I with my reputation,\nCome I with my testimony,\nCome I to Thee, Jesu,\nJesu, shelter me.","note":"A morning prayer of coming to God, whole, from head to foot.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1030.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-soul-plaint","title":"The Soul Plaint","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"prayer","occasion":["evening","comfort","healing"],"text":"O Jesu! to-night,\nThou Shepherd of the poor,\nThou sinless person\nWho didst suffer full sore,\nBy ban of the wicked,\nAnd wast crucified.\n\nSave me from evil,\nSave me from harm,\nSave Thou my body,\nSanctify me to-night,\nO Jesu! to-night,\nNor leave me.\n\nEndow me with strength,\nThou Herdsman of might.\nGuide me aright,\nGuide me in Thy strength,\nO Jesu! in Thy strength\nPreserve me.","note":"A night prayer to Christ the Shepherd for strength and guidance.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1031.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-sleeping-prayer","title":"Sleeping Prayer","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"prayer","occasion":["evening","peace","dying"],"text":"I am placing my soul and my body\nOn Thy sanctuary this night, O God,\nOn Thy sanctuary, O Jesus Christ,\nOn Thy sanctuary, O Spirit of perfect truth,\nThe Three who would defend my cause,\nNor turn Their backs upon me.\n\nThou, Father, who art kind and just,\nThou, Son, who didst overcome death,\nThou, Holy Spirit of power,\nBe keeping me this night from harm;\nThe Three who would justify me\nKeeping me this night and always.","note":"A night prayer placing body and soul in God's keeping.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1032.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-gifts-of-the-three","title":"The Gifts of the Three","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"prayer","occasion":["evening","daily"],"text":"Spirit, give me of Thine abundance,\nFather, give me of Thy wisdom,\nSon, give me in my need,\nJesus beneath the shelter of Thy shield.\n\nI lie down to-night,\nWith the Triune of my strength,\nWith the Father, with Jesus,\nWith the Spirit of might.","note":"A short prayer for lying down with the Three of strength.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1033.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-resting-blessing","title":"From the Resting Blessing","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"blessing","occasion":["evening","peace"],"text":"In name of the Lord Jesus,\nAnd of the Spirit of healing balm,\nIn name of the Father of Israel,\nI lay me down to rest.\n\nIf there be evil threat or quirk,\nOr covert act intent on me,\nGod free me and encompass me,\nAnd drive from me mine enemy.\n\nIn name of the Father precious,\nAnd of the Spirit of healing balm,\nIn name of the Lord Jesus,\nI lay me down to rest.","note":"A simple blessing for lying down to rest.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1035.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-bed-blessing","title":"Bed Blessing","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"blessing","occasion":["evening","peace"],"text":"I am lying down to-night as beseems\nIn the fellowship of Christ, son of the Virgin of ringlets.\nIn the fellowship of the gracious Father of glory,\nIn the fellowship of the Spirit of powerful aid.\n\nI am lying down to-night with God,\nAnd God to-night will lie down with me,\nI will not lie down to-night with sin, nor shall\nSin nor sin's shadow lie down with me.\n\nI am lying down to-night with the Holy Spirit,\nAnd the Holy Spirit this night will lie down with me,\nI will lie down this night with the Three of my love,\nAnd the Three of my love will lie down with me.","note":"A bedtime blessing of lying down in the fellowship of the Three.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1037.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-the-sleep-prayer","title":"The Sleep Prayer","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"prayer","occasion":["evening","dying","comfort"],"text":"I am now going into the sleep,\nBe it that I in health shall waken;\nIf death be to me in the death-sleep,\nBe it that on Thine own arm,\nO God of Grace, I in peace shall waken;\nBe it on Thine own beloved arm,\nO God of Grace, that I in peace shall waken.\n\nBe my soul on Thy right hand, O God,\nThou King of the heaven of heavens;\nThou it was who bought'st me with Thy blood,\nThou it was who gavest Thy life for me,\nEncompass Thou me this night, O God,\nThat no harm, no evil shall me befall.\n\nWhilst the body is dwelling in the sleep,\nThe soul is soaring in the shadow of heaven,\nBe the red-white Michael meeting the soul,\nEarly and late, night and day,\nEarly and late, night and day.\nAmen.","note":"A night prayer for waking in health or waking in peace on God's arm; often prayed at a bedside near the end of life.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1038.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-sleep-consecration","title":"Sleep Consecration","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"prayer","occasion":["evening","grief","comfort"],"text":"I am lying down to-night,\nWith Father, with Son,\nWith the Spirit of Truth,\nWho shield me from harm.\n\nI will not lie with evil,\nNor shall evil lie with me,\nBut I will lie down with God,\nAnd God will lie down with me.\n\nGod and Christ and Spirit Holy,\nAnd the cross of the nine white angels,\nBe protecting me as Three and as One,\nFrom the top tablet of my face to the soles of my feet.\n\nThou King of the sun and of glory,\nThou Jesu, Son of the Virgin fragrant,\nKeep Thou us from the glen of tears,\nAnd from the house of grief and gloom,\nKeep us from the glen of tears,\nFrom the house of grief and gloom.","note":"A night prayer asking to be kept from the glen of tears and the house of grief.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1039.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-soul-shrine","title":"The Soul Shrine","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"prayer","occasion":["home","evening","grief","gratitude"],"text":"God, give charge to Thy blessed angels,\nTo keep guard around this stead to-night,\nA band sacred, strong, and steadfast,\nThat will shield this soul-shrine from harm.\n\nSafeguard Thou, God, this household to-night,\nThemselves and their means and their fame,\nDeliver them from death, from distress, from harm,\nFrom the fruits of envy and of enmity.\n\nGive Thou to us, O God of peace,\nThankfulness despite our loss,\nTo obey Thy statutes here below,\nAnd to enjoy Thyself above.","note":"A prayer over a household at night, asking for thankfulness despite our loss.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1041.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-soul-shrine-angel","title":"Soul-Shrine","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"prayer","occasion":["evening","dying","comfort"],"text":"Thou angel of God who hast charge of me\nFrom the fragrant Father of mercifulness,\nThe gentle encompassing of the Sacred Heart\nTo make round my soul-shrine this night,\nOh, round my soul-shrine this night.\n\nWard from me every distress and danger,\nEncompass my course over the ocean of truth,\nI pray thee, place thy pure light before me,\nO bright beauteous angel on this very night,\nBright beauteous angel on this very night.\n\nBe Thyself the guiding star above me,\nIllume Thou to me every reef and shoal,\nPilot my barque on the crest of the wave,\nTo the restful haven of the waveless sea,\nOh, the restful haven of the waveless sea.","note":"A prayer to the guardian angel to pilot the soul to the restful haven of the waveless sea.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1042.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-i-lie-in-my-bed","title":"I Lie in My Bed","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"prayer","occasion":["evening","dying","funeral","comfort"],"text":"I lie in my bed\nAs I would lie in the grave,\nThine arm beneath my neck,\nThou Son of Mary victorious.\n\nAngels shall watch me\nAnd I lying in slumber,\nAnd angels shall guard me\nIn the sleep of the grave.\n\nUriel shall be at my feet,\nAriel shall be at my back,\nGabriel shall be at my head,\nAnd Raphael shall be at my side.\n\nMichael shall be with my soul,\nThe strong shield of my love!\nAnd the Physician Son of Mary\nShall put the salve to mine eye,\nThe Physician Son of Mary\nShall put the salve to mine eye!","note":"A night prayer that sees sleep and the grave as held alike by Christ and the angels.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1043.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-morning-prayer","title":"From Morning Prayer","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"prayer","occasion":["morning","gratitude"],"text":"Thanks be to Thee, Jesus Christ,\nWho brought'st me up from last night,\nTo the gladsome light of this day,\nTo win everlasting life for my soul,\nThrough the blood Thou didst shed for me.\n\nAnd I beseech Thee\nTo shield me from sin,\nTo shield me from ill,\nTo sain me this night,\nAnd I low and poor,\nO God of the poor!\nO Christ of the wounds!\nGive me wisdom along with Thy grace.\n\nMay the Holy One claim me,\nAnd protect me on sea and on land,\nAnd lead me on from step to step,\nTo the peace of the Everlasting City,\nThe peace of the Everlasting City!","note":"A morning prayer of thanks for being brought up from last night to the light of this day.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1044.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-the-dedication","title":"The Dedication","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"prayer","occasion":["morning","gratitude","daily"],"text":"Thanks to Thee, God,\nWho brought'st me from yesterday\nTo the beginning of to-day,\nEverlasting joy\nTo earn for my soul\nWith good intent.\nAnd for every gift of peace\nThou bestowest on me,\nMy thoughts, my words,\nMy deeds, my desires\nI dedicate to Thee.\nI supplicate Thee,\nI beseech Thee,\nTo keep me from offence,\nAnd to shield me to-night,\nFor the sake of Thy wounds\nWith Thine offering of grace.","note":"A morning prayer dedicating thoughts, words, deeds, and desires to God.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1045.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-resting-prayer","title":"A Resting Prayer","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"prayer","occasion":["home","evening"],"text":"God shield the house, the fire, the kine,\nEvery one who dwells herein to-night.\nShield myself and my beloved group,\nPreserve us from violence and from harm;\nPreserve us from foes this night,\nFor the sake of the Son of the Mary Mother,\nIn this place, and in every place wherein they dwell to-night,\nOn this night and on every night,\nThis night and every night.","note":"A night prayer over the house, the fire, and everyone who dwells there.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1046.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-house-protecting","title":"House Protecting","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"blessing","occasion":["home","morning","evening","blessing"],"text":"God, bless the world and all that is therein.\nGod, bless my spouse and my children,\nGod, bless the eye that is in my head,\nAnd bless, O God, the handling of my hand;\nWhat time I rise in the morning early,\nWhat time I lie down late in bed,\nBless my rising in the morning early,\nAnd my lying down late in bed.\n\nGod, protect the house, and the household,\nGod, consecrate the children of the motherhood,\nGod, encompass the flocks and the young;\nBe Thou after them and tending them,\nWhat time the flocks ascend hill and wold,\nWhat time I lie down to sleep,\nWhat time the flocks ascend hill and wold,\nWhat time I lie down in peace to sleep.","note":"A blessing on the world, the household, and the work of one's hands.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1047.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-blessing-of-house","title":"Blessing of House","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian","all"],"denom":["scottish"],"type":"blessing","occasion":["home","blessing"],"text":"God bless the house,\nFrom site to stay,\nFrom beam to wall,\nFrom end to end,\nFrom ridge to basement,\nFrom balk to roof-tree,\nFrom found to summit,\nFound and summit.","note":"A short blessing of a house from its foundation to its roof tree.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1048.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-to-whom-oblation","title":"To Whom Shall I Offer Oblation","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"prayer","occasion":["dying","hope"],"text":"To whom shall I offer oblation\nIn name of Michael on high?\nI will give tithe of my means\nTo the forsaken illustrious One.\n\nBecause of all that I have seen,\nOf His peace and of His mercy,\nLift Thou my soul to Thee, O Son of God,\nNor leave me ever.\n\nRemember me in the mountain,\nUnder Thy wing shield Thou me;\nRock of truth, do not forsake me,\nMy wish it were ever to be near Thee.\n\nGive to me the wedding garment,\nBe angels conversing with me in every need,\nBe the holy apostles protecting me,\nThe fair Mary and Thou, Jesu of grace,\nThe fair Mary and Thou, Jesu of grace.","note":"A prayer to be lifted to God and never left alone.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1049.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-hail-mary-celtic","title":"Hail, Mary","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian","catholic"],"denom":["scottish"],"type":"prayer","occasion":["comfort","hope"],"text":"Hail, Mary! hail, Mary!\nQueen of grace, Mother of mercy;\nHail, Mary, in manner surpassing,\nFount of our health, source of our joy.\n\nTo thee we, night and day,\nErring children of Adam and Eve,\nLift our voice in supplication,\nIn groans and grief and tears.\n\nBestow upon us, thou Root of gladness,\nSince thou art the cup of generous graces,\nThe faith of John, and Peter, and Paul,\nWith the wings of Ariel on the heights of the clouds.\n\nVouchsafe to us, thou golden branch,\nA mansion in the Realm of peace,\nRest from the perils and stress of waves,\nBeneath the shade of the fruit of thy womb, Jesu.","note":"A Gaelic hymn to Mary, Queen of grace and Mother of mercy.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1050.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-battle-to-come","title":"The Battle to Come","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"prayer","occasion":["dying","funeral"],"text":"Jesus, Thou Son of Mary, I call on Thy name,\nAnd on the name of John the apostle beloved,\nAnd on the names of all the saints in the red domain,\nTo shield me in the battle to come,\nTo shield me in the battle to come.\n\nWhen the mouth shall be closed,\nWhen the eye shall be shut,\nWhen the breath shall cease to rattle,\nWhen the heart shall cease to throb,\nWhen the heart shall cease to throb.\n\nWhen the Judge shall take the throne,\nAnd when the cause is fully pleaded,\nO Jesu, Son of Mary, shield Thou my soul,\nO Michael fair, acknowledge my departure.\nO Jesu, Son of Mary, shield Thou my soul!\nO Michael fair, receive my departure!","note":"A prayer for the hour of death, asking Christ to shield the soul and Michael to receive its departure.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1052.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-baptism-blessing","title":"The Baptism Blessing","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"blessing","occasion":["birth","blessing"],"text":"Thou Being who inhabitest the heights\nImprint Thy blessing betimes,\nRemember Thou the child of my body,\nIn Name of the Father of peace;\nWhen the priest of the King\nOn him puts the water of meaning,\nGrant him the blessing of the Three\nWho fill the heights.\nThe blessing of the Three\nWho fill the heights.\n\nSprinkle down upon him Thy grace,\nGive Thou to him virtue and growth,\nGive Thou to him strength and guidance,\nGive Thou to him flocks and possessions,\nSense and reason void of guile,\nAngel wisdom in his day,\nThat he may stand without reproach\nIn Thy presence.\nHe may stand without reproach\nIn Thy presence.","note":"A mother's blessing for her child at baptism, asking for virtue, growth, and angel wisdom.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1053.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-soul-leading","title":"The Soul Leading","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"prayer","occasion":["dying","funeral"],"text":"Be this soul on Thine arm, O Christ,\nThou King of the City of Heaven,\nAmen.\nSince Thou, O Christ, it was who bought'st this soul,\nBe its peace on Thine own keeping.\nAmen.\nAnd may the strong Michael, high king of the angels,\nBe preparing the path before this soul, O God.\nAmen.\nOh! the strong Michael in peace with thee, soul,\nAnd preparing for thee the way to the kingdom of the Son of God.\nAmen.","note":"Said at a deathbed, asking Michael to prepare the path before the soul.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1054.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-death-blessing","title":"From the Death Blessing","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"blessing","occasion":["dying","funeral"],"text":"Be this soul on Thine own arm, O Christ,\nThou King of the City of Heaven,\nAnd since Thine it was, O Christ, to buy the soul,\nAt the time of the balancing of the beam,\nAt the time of the bringing in the judgment,\nBe it now on Thine own right hand,\nOh! on Thine own right hand.\n\nAnd be the holy Michael, king of angels,\nComing to meet the soul,\nAnd leading it home\nTo the heaven of the Son of God.\nThe Holy Michael, high king of angels,\nComing to meet the soul,\nAnd leading it home\nTo the heaven of the Son of God.","note":"Said over the dying, asking Michael to meet the soul and lead it home.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1055.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-soul-peace","title":"Soul Peace","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"prayer","occasion":["dying","funeral","peace"],"text":"Since Thou Christ it was who didst buy the soul,\nAt the time of yielding the life,\nAt the time of pouring the sweat,\nAt the time of offering the clay,\nAt the time of shedding the blood,\nAt the time of balancing the beam,\nAt the time of severing the breath,\nAt the time of delivering the judgment,\nBe its peace upon Thine own ingathering;\nJesus Christ Son of gentle Mary,\nBe its peace upon Thine own ingathering,\nO Jesus! upon Thine own ingathering.\n\nAnd may Michael white kindly,\nHigh king of the holy angels,\nTake possession of the beloved soul,\nAnd shield it home to the Three of surpassing love,\nOh! to the Three of surpassing love.","note":"Sung over the dying by the soul friend, asking peace for the soul at every stage of its leaving.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1056.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-new-moon","title":"The New Moon","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"blessing","occasion":["nature","evening","season"],"text":"In name of the Holy Spirit of grace,\nIn name of the Father of the City of peace,\nIn name of Jesus who took death off us,\nOh! in name of the Three who shield us in every need,\nIf well thou hast found us to-night,\nSeven times better mayest thou leave us without harm,\nThou bright white Moon of the seasons,\nBright white Moon of the seasons.","note":"A greeting to the new moon in the name of the Three.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1057.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-christmas-carol","title":"Christmas Carol","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"hymn","occasion":["season","celebration"],"text":"Hail King! hail King! blessed is He! blessed is He!\nHail King! hail King! blessed is He! blessed is He!\nHail King! hail King! blessed is He, the King of whom we sing,\nAll hail! let there be joy!\n\nThis night is the eve of the great Nativity,\nBorn is the Son of Mary the Virgin,\nThe soles of His feet have reached the earth,\nThe Son of glory down from on high,\nHeaven and earth glowed to Him,\nAll hail! let there be joy!\n\nThe peace of earth to Him, the joy of heaven to Him,\nBehold His feet have reached the world;\nThe homage of a King be His, the welcome of a Lamb be His,\nKing all victorious, Lamb all glorious,\nEarth and ocean illumed to Him,\nAll hail! let there be joy!\n\nThe mountains glowed to Him, the plains glowed to Him,\nThe voice of the waves with the song of the strand,\nAnnouncing to us that Christ is born,\nSon of the King of kings from the land of salvation;\nShone the sun on the mountains high to Him,\nAll hail! let there be joy!\n\nShone to Him the earth and sphere together,\nGod the Lord has opened a Door;\nSon of Mary Virgin, hasten Thou to help me,\nThou Christ of hope, Thou Door of joy,\nGolden Sun of hill and mountain,\nAll hail! let there be joy!","note":"A Christmas carol of the islands: the mountains, the plains, and the waves glowing to the newborn King.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1060.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-hey-the-gift","title":"Hey the Gift, Ho the Gift","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"hymn","occasion":["season","nature","celebration"],"text":"Hey the Gift, ho the Gift,\nHey the Gift, on the living.\n\nSon of the dawn, Son of the clouds,\nSon of the planet, Son of the star,\nHey the Gift, ho the Gift,\nHey the Gift, on the living.\n\nSon of the rain, Son of the dew,\nSon of the welkin, Son of the sky,\nHey the Gift, ho the Gift,\nHey the Gift, on the living.\n\nSon of the flame, Son of the light,\nSon of the sphere, Son of the globe,\nHey the Gift, ho the Gift,\nHey the Gift, on the living.\n\nSon of the elements, Son of the heavens,\nSon of the moon, Son of the sun,\nHey the Gift, ho the Gift,\nHey the Gift, on the living.\n\nSon of Mary of the God-mind,\nAnd the Son of God first of all news,\nHey the Gift, ho the Gift,\nHey the Gift, on the living.","note":"A Christmas chant naming Christ as Son of the dawn, the rain, the dew, the moon, and the sun.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1063.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-shepherd-of-the-flock","title":"The Shepherd of the Flock Was Born","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"hymn","occasion":["season","birth"],"text":"That night the star shone\nWas born the Shepherd of the Flock,\nOf the Virgin of the hundred charms;\nThe Mary Mother.\n\nThe Trinity eternal by her side,\nIn the manger cold and lowly.\nCome and give tithes of thy means\nTo the Healing Man.\n\nThe foam-white breastling beloved,\nWithout one home in the world,\nThe tender holy Babe forth driven,\nImmanuel!\n\nYe three angels of power,\nCome ye, come ye down;\nTo the Christ of the people\nGive ye salutation.\n\nKiss ye His hands,\nDry ye His feet\nWith the hair of your heads;\nAnd O! Thou world-pervading God,\nAnd Ye, Jesu, Michael, Mary,\nDo not Ye forsake us.","note":"A Christmas hymn of the Babe born without one home in the world.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1066.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-blessing-new-year","title":"The Blessing of the New Year","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian","all"],"denom":["scottish"],"type":"blessing","occasion":["season","morning","blessing"],"text":"God, bless to me the new day,\nNever vouchsafed to me before;\nIt is to bless Thine own presence\nThou hast given me this time, O God.\n\nBless Thou to me mine eye,\nMay mine eye bless all it sees;\nI will bless my neighbour,\nMay my neighbour bless me.\n\nGod, give me a clean heart,\nLet me not from sight of Thine eye;\nBless to me my children and my wife,\nAnd bless to me my means and my cattle.","note":"A blessing for a new day or a new year: may mine eye bless all it sees.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1071.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-thursday-of-columba","title":"From the Day of Saint Columba","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"chant","occasion":["season","daily"],"text":"Thursday of Columba benign,\nDay to send sheep on prosperity,\nDay to send cow on calf,\nDay to put the web in the warp.\n\nDay to put coracle on the brine,\nDay to place the staff to the flag,\nDay to bear, day to die,\nDay to hunt the heights.\n\nDay to put horses in harness,\nDay to send herds to pasture,\nDay to make prayer efficacious,\nDay of my beloved, the Thursday,\nDay of my beloved, the Thursday.","note":"A chant for Saint Columba's Thursday, the island day for good beginnings.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1073.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-bride-aid-woman","title":"Bride the Aid-Woman","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian","catholic"],"denom":["scottish"],"type":"prayer","occasion":["birth","healing"],"text":"There came to me assistance,\nMary fair and Bride;\nAs Anna bore Mary,\nAs Mary bore Christ,\nAs Eile bore John the Baptist\nWithout flaw in him,\nAid thou me in mine unbearing,\nAid me, O Bride!\n\nAs Christ was conceived of Mary\nFull perfect on every hand,\nAssist thou me, foster-mother,\nThe conception to bring from the bone;\nAnd as thou didst aid the Virgin of joy,\nWithout gold, without corn, without kine,\nAid thou me, great is my sickness,\nAid me, O Bride!","note":"A prayer said at a birth, asking Saint Bride to aid the mother.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1076.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-beltane-blessing","title":"The Beltane Blessing","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"blessing","occasion":["season","home","blessing"],"text":"Bless, O Threefold true and bountiful,\nMyself, my spouse, and my children,\nMy tender children and their beloved mother at their head.\nOn the fragrant plain, on the gay mountain sheiling,\nOn the fragrant plain, on the gay mountain sheiling.\n\nEverything within my dwelling or in my possession,\nAll kine and crops, all flocks and corn,\nFrom Hallow Eve to Beltane Eve,\nWith goodly progress and gentle blessing,\nFrom sea to sea, and every river mouth,\nFrom wave to wave, and base of waterfall.\n\nBe the Three Persons taking possession of all to me belonging,\nBe the sure Trinity protecting me in truth;\nOh! satisfy my soul in the words of Paul,\nAnd shield my loved ones beneath the wing of Thy glory,\nShield my loved ones beneath the wing of Thy glory.\n\nBless everything and every one,\nOf this little household by my side;\nPlace the cross of Christ on us with the power of love,\nTill we see the land of joy,\nTill we see the land of joy,\n\nWhat time the kine shall forsake the stalls,\nWhat time the sheep shall forsake the folds,\nWhat time the goats shall ascend to the mount of mist,\nMay the tending of the Triune follow them,\nMay the tending of the Triune follow them.\n\nThou Being who didst create me at the beginning,\nListen and attend me as I bend the knee to Thee,\nMorning and evening as is becoming in me,\nIn Thine own presence, O God of life,\nIn Thine own presence, O God of life.","note":"A May Day blessing on the family, the household, and the flocks going up to the summer pastures.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1078.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-feast-day-of-mary","title":"The Feast Day of Mary","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"prayer","occasion":["season","gratitude","home"],"text":"On the feast day of Mary the fragrant,\nMother of the Shepherd of the flocks,\nI cut me a handful of the new corn,\nI dried it gently in the sun,\nI rubbed it sharply from the husk\nWith mine own palms.\n\nI ground it in a quern on Friday,\nI baked it on a fan of sheep-skin,\nI toasted it to a fire of rowan,\nAnd I shared it round my people.\n\nI went sunways round my dwelling,\nIn name of the Mary Mother,\nWho promised to preserve me,\nWho did preserve me,\nAnd who will preserve me,\nIn peace, in flocks,\nIn righteousness of heart,\nIn labour, in love,\nIn wisdom, in mercy,\nFor the sake of Thy Passion.\nThou Christ of grace\nWho till the day of my death\nWilt never forsake me!\nOh, till the day of my death\nWilt never forsake me!","note":"A harvest prayer of cutting, baking, and sharing the first new corn with one's people.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1082.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-michael-victorious","title":"Michael, the Victorious","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"prayer","occasion":["blessing","daily"],"text":"Thou Michael the victorious,\nI make my circuit under thy shield,\nThou Michael of the white steed,\nAnd of the bright brilliant blades,\nConqueror of the dragon,\nBe thou at my back,\nThou ranger of the heavens,\nThou warrior of the King of all,\nO Michael the victorious,\nMy pride and my guide,\nO Michael the victorious,\nThe glory of mine eye.\n\nI make my circuit\nIn the fellowship of my saint,\nOn the machair, on the meadow,\nOn the cold heathery hill;\nThough I should travel ocean\nAnd the hard globe of the world\nNo harm can e'er befall me\n'Neath the shelter of thy shield;\nO Michael the victorious,\nJewel of my heart,\nO Michael the victorious,\nGod's shepherd thou art.\n\nBe the sacred Three of Glory\nAye at peace with me,\nWith my horses, with my cattle,\nWith my woolly sheep in flocks.\nWith the crops growing in the field\nOr ripening in the sheaf,\nOn the machair, on the moor,\nIn cole, in heap, or stack.\nEvery thing on high or low,\nEvery furnishing and flock,\nBelong to the holy Triune of glory,\nAnd to Michael the victorious.","note":"A journey prayer: making one's circuit under the shield of Michael.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1084.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-blessing-of-kindling","title":"Blessing of the Kindling","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"blessing","occasion":["morning","home","daily"],"text":"I will kindle my fire this morning\nIn presence of the holy angels of heaven,\nIn presence of Ariel of the loveliest form,\nIn presence of Uriel of the myriad charms,\nWithout malice, without jealousy, without envy,\nWithout fear, without terror of any one under the sun,\nBut the Holy Son of God to shield me.\nWithout malice, without jealousy, without envy,\nWithout fear, without terror of any one under the sun,\nBut the Holy Son of God to shield me.\n\nGod, kindle Thou in my heart within\nA flame of love to my neighbour,\nTo my foe, to my friend, to my kindred all,\nTo the brave, to the knave, to the thrall,\nO Son of the loveliest Mary,\nFrom the lowliest thing that liveth,\nTo the Name that is highest of all.\nO Son of the loveliest Mary,\nFrom the lowliest thing that liveth,\nTo the Name that is highest of all.","note":"Said while kindling the morning fire, asking God to kindle a flame of love in the heart.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1090.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-kindling-the-fire","title":"Kindling the Fire","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"blessing","occasion":["morning","home"],"text":"I will raise the hearth-fire\nAs Mary would.\nThe encirclement of Bride and of Mary\nOn the fire, and on the floor,\nAnd on the household all.\n\nWho are they on the bare floor?\nJohn and Peter and Paul.\nWho are they by my bed?\nThe lovely Bride and her Fosterling.\nWho are those watching over my sleep?\nThe fair loving Mary and her Lamb.\nWho is that anear me?\nThe King of the sun, He himself it is.\nWho is that at the back of my head?\nThe Son of Life without beginning, without time.","note":"Said while raising the hearth fire in the morning.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1091.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-smooring-sacred-three","title":"Smooring the Fire","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"blessing","occasion":["evening","home","peace"],"text":"The sacred Three\nTo save,\nTo shield,\nTo surround\nThe hearth,\nThe house,\nThe household,\nThis eve,\nThis night,\nOh! this eve,\nThis night,\nAnd every night,\nEach single night.\nAmen.","note":"Said while banking the fire for the night: the sacred Three to save, to shield, to surround.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1092.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-smooring-the-hearth","title":"I Will Build the Hearth","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"blessing","occasion":["evening","home"],"text":"I will build the hearth,\nAs Mary would build it.\nThe encompassment of Bride and of Mary,\nGuarding the hearth, guarding the floor,\nGuarding the household all.\n\nWho are they on the lawn without?\nMichael the sun-radiant of my trust.\nWho are they on the middle of the floor?\nJohn and Peter and Paul.\nWho are they by the front of my bed?\nSun-bright Mary and her Son.\n\nThe mouth of God ordained,\nThe angel of God proclaimed,\nAn angel white in charge of the hearth\nTill white day shall come to the embers.\nAn angel white in charge of the hearth\nTill white day shall come to the embers.","note":"A smooring prayer for banking the fire at night, with an angel in charge of the hearth till white day.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1093.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-blessing-of-smooring","title":"Blessing of the Smooring","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"blessing","occasion":["evening","home","peace"],"text":"I am smooring the fire\nAs the Son of Mary would smoor;\nBlest be the house, blest be the fire,\nBlest be the people all.\n\nWho are those down on the floor?\nJohn and Peter and Paul.\nOn whom is the vigil to-night?\nOn the fair gentle Mary and on her Son.\n\nThe mouth of God said,\nThe angel of God spake,\nAn angel in the door of the house,\nTo guard and to keep us all\nTill comes daylight to-morrow.\n\nOh! may the angels of the Holy One of God\nEnviron me all this night,\nOh! may the angels of the Anointed One of God\nEncompass me from harm and from evil,\nOh! encompass me from harm this night.","note":"A night blessing on the house, the fire, and the people.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1094.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-consecration-of-seed","title":"From the Consecration of the Seed","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"blessing","occasion":["season","nature","hope"],"text":"I will go out to sow the seed,\nIn name of Him who gave it growth;\nI will place my front in the wind,\nAnd throw a gracious handful on high.\nShould a grain fall on a bare rock,\nIt shall have no soil in which to grow;\nAs much as falls into the earth,\nThe dew will make it to be full.\n\nFriday, day auspicious,\nThe dew will come down to welcome\nEvery seed that lay in sleep\nSince the coming of cold without mercy;\nEvery seed will take root in the earth,\nAs the King of the elements desired,\nThe braird will come forth with the dew,\nIt will inhale life from the soft wind.\n\nI will come round with my step,\nI will go rightways with the sun,\nIn name of Ariel and the angels nine,\nIn name of Gabriel and the Apostles kind.\n\nFather, Son, and Spirit Holy,\nBe giving growth and kindly substance\nTo every thing that is in my ground,\nTill the day of gladness shall come.","note":"A spring blessing said while sowing the seed.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1096.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-reaping-blessing","title":"Reaping Blessing","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"blessing","occasion":["season","gratitude","nature"],"text":"God, bless Thou Thyself my reaping,\nEach ridge, and plain, and field,\nEach sickle curved, shapely, hard,\nEach ear and handful in the sheaf,\nEach ear and handful in the sheaf.\n\nBless each maiden and youth,\nEach woman and tender youngling,\nSafeguard them beneath Thy shield of strength,\nAnd guard them in the house of the saints,\nGuard them in the house of the saints.\n\nEncompass each goat, sheep and lamb,\nEach cow and horse, and store,\nSurround Thou the flocks and herds,\nAnd tend them to a kindly fold,\nTend them to a kindly fold.\n\nFor the sake of Michael head of hosts,\nOf Mary fair-skinned branch of grace,\nOf Bride smooth-white of ringleted locks,\nOf Columba of the graves and tombs,\nColumba of the graves and tombs.","note":"A harvest blessing on the reaping, the young, and the flocks.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1097.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-reaping-thanks","title":"From the Reaping Blessing","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"blessing","occasion":["season","gratitude"],"text":"On Tuesday of the feast at the rise of the sun,\nAnd the back of the ear of corn to the east,\nI will go forth with my sickle under my arm,\nAnd I will reap the cut the first act.\n\nI will let my sickle down\nWhile the fruitful ear is in my grasp,\nI will raise mine eye upwards,\nI will turn me on my heel quickly,\n\nRightway as travels the sun\nFrom the airt of the east to the west,\nFrom the airt of the north with motion calm\nTo the very core of the airt of the south.\n\nI will give thanks to the King of grace\nFor the growing crops of the ground,\nHe will give food to ourselves and to the flocks\nAccording as He disposeth to us.","note":"Said at the first cutting of the harvest, giving thanks for the growing crops.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1098.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-blessing-of-parching","title":"The Blessing of the Parching","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"blessing","occasion":["home","gratitude"],"text":"Thou flame grey, slender, curved,\nComing from the top pore of the peat,\nThou flame of leaps, breadth, heat,\nCome not nigh me with thy quips.\n\nA burning steady, gentle, generous,\nComing round about my quicken roots,\nA fire fragrant, fair, and peaceful,\nNor causes dust, nor grief, nor havoc.\n\nHeat, parch my fat seed,\nFor food for my little child,\nIn name of Christ, King of the elements,\nWho gave us corn and bread and blessing withal,\nIn name of Christ, King of the elements,\nWho gave us corn and bread and blessing withal.","note":"Said while drying grain at the fire, giving thanks for corn and bread.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1099.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-herding-blessing","title":"Herding Blessing","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"blessing","occasion":["blessing","nature"],"text":"Travelling moorland, travelling townland,\nTravelling mossland long and wide,\nBe the herding of God the Son about your feet,\nSafe and whole may ye home return,\nBe the herding of God the Son about your feet,\nSafe and whole may ye home return.\n\nThe sanctuary of Carmac and of Columba\nBe protecting you going and coming,\nAnd of the milkmaid of the soft palms,\nBride of the clustering hair golden brown,\nAnd of the milkmaid of the soft palms,\nBride of the clustering hair golden brown.","note":"A blessing on the herds going out to pasture: safe and whole may ye home return.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1111.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-protection-of-cattle","title":"The Protection of the Cattle","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"blessing","occasion":["blessing","nature","home"],"text":"Pastures smooth, long, and spreading,\nGrassy meads aneath your feet,\nThe friendship of God the Son to bring you home\nTo the field of the fountains,\nField of the fountains.\n\nClosed be every pit to you,\nSmoothed be every knoll to you,\nCosy every exposure to you,\nBeside the cold mountains,\nBeside the cold mountains.\n\nThe care of Peter and of Paul,\nThe care of James and of John,\nThe care of Bride fair and of Mary Virgin,\nTo meet you and to tend you,\nOh! the care of all the band\nTo protect you and to strengthen you.","note":"A blessing for the cattle going out: smoothed be every knoll to you.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1112.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-guarding-the-flocks","title":"Guarding the Flocks","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"blessing","occasion":["nature","blessing"],"text":"May Mary the mild keep the sheep,\nMay Bride the calm keep the sheep,\nMay Columba keep the sheep,\nMay Maolruba keep the sheep,\nMay Carmac keep the sheep,\nFrom the fox and the wolf.\n\nMay Oran keep the kine,\nMay Modan keep the kine,\nMay Dorman keep the kine,\nMay Moluag keep the kine,\nMay Maolruan keep the kine,\nOn soft land and hard land.\n\nMay the Spirit of peace preserve the flocks,\nMay the Son of Mary Virgin preserve the flocks,\nMay the God of glory preserve the flocks,\nMay the Three preserve the flocks,\nFrom wounding and from death-loss,\nFrom wounding and from death-loss.","note":"A blessing asking the Celtic saints to keep the sheep and kine.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1113.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-prayer-for-travelling","title":"Prayer for Travelling","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"prayer","occasion":["blessing","daily"],"text":"Life be in my speech,\nSense in what I say,\nThe bloom of cherries on my lips,\nTill I come back again.\n\nThe love Christ Jesus gave\nBe filling every heart for me,\nThe love Christ Jesus gave\nFilling me for every one.\n\nTraversing corries, traversing forests,\nTraversing valleys long and wild.\nThe fair white Mary still uphold me,\nThe Shepherd Jesu be my shield,\nThe fair white Mary still uphold me,\nThe Shepherd Jesu be my shield.","note":"A journey prayer: the love Christ Jesus gave be filling every heart for me.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1126.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-fishing-blessing","title":"From the Fishing Blessing","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"blessing","occasion":["blessing","daily"],"text":"The day of light has come upon us,\nChrist is born of the Virgin.\n\nIn His name I sprinkle the water\nUpon every thing within my court.\n\nThou King of deeds and powers above,\nThy fishing blessing pour down on us.\n\nEncompass ye us to the fishing-bank of ocean,\nAnd still ye to us the crest of the waves.\n\nBe the King of kings at the end of our course,\nOf lengthened life and of lasting happiness.\n\nBe the crown of the King from the Three on high,\nBe the cross of Christ adown to shield us,\nThe crown of the King from the Three above,\nThe cross of Christ adown to shield us.","note":"A blessing for going out to fish on the sea.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1127.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-ocean-blessing","title":"From the Ocean Blessing","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"prayer","occasion":["blessing","peace"],"text":"O Thou who pervadest the heights,\nImprint on us Thy gracious blessing,\nCarry us over the surface of the sea,\nCarry us safely to a haven of peace,\nBless our boatmen and our boat,\nBless our anchors and our oars,\nEach stay and halyard and traveller,\nOur mainsails to our tall masts\nKeep, O King of the elements, in their place\nThat we may return home in peace;\nI myself will sit down at the helm,\nIt is God's own Son who will give me guidance,\nAs He gave to Columba the mild\nWhat time he set stay to sails.\n\nOn the Day of the Three Kings on high,\nSubdue to us the crest of the waves,\nOn Beltane Day give us the dew,\nOn John's Day the gentle wind,\nThe Day of Mary the great of fame,\nWard off us the storm from the west;\nEach day and night, storm and calm,\nBe Thou with us, O Chief of chiefs,\nBe Thou Thyself to us a compass-chart,\nBe Thine hand on the helm of our rudder,\nThine own hand, Thou God of the elements,\nEarly and late as is becoming,\nEarly and late as is becoming.","note":"A blessing on the boat and the crew before a voyage; the King of the elements at the helm.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1129.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-ruler-of-elements","title":"Ruler of the Elements","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"prayer","occasion":["blessing","peace"],"text":"The Children of Israel, God taking them,\nThrough the Red Sea obtained a path,\nThey obtained the quenching of their thirst\nFrom a rock that might not by craftsman be hewn.\n\nWho are they on the tiller of my rudder,\nGiving speed to my east bound barge?\nPeter and Paul and John the beloved,\nThree to whom laud and obeisance are due.\n\nWho are the group near to my helm?\nPeter and Paul and John the Baptist;\nChrist is sitting on my helm,\nMaking guidance to the wind from the south.\n\nTo whom does tremble the voice of the wind?\nTo whom become tranquil strait and ocean?\nTo Jesus Christ, Chief of each saint,\nSon of Mary, Root of victory,\nSon of Mary, Root of victory.","note":"A sea prayer: Christ is sitting on my helm.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1131.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-sea-prayer","title":"Sea Prayer","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"litany","occasion":["blessing","peace","comfort"],"text":"Blest be the boat.\n\nGod the Father bless her.\n\nBlest be the boat.\n\nGod the Son bless her.\n\nBlest be the boat.\n\nGod the Spirit bless her.\n\nGod the Father,\nGod the Son,\nGod the Spirit,\nBless the boat.\n\nWhat can befall you\nAnd God the Father with you?\n\nNo harm can befall us.\n\nWhat can befall you\nAnd God the Son with you?\n\nNo harm can befall us.\n\nWhat can befall you\nAnd God the Spirit with you?\n\nNo harm can befall us.\n\nGod the Father,\nGod the Son,\nGod the Spirit,\nWith us eternally.\n\nWhat can cause you anxiety\nAnd the God of the elements over you?\n\nNo anxiety can be ours.\n\nWhat can cause you anxiety\nAnd the King of the elements over you?\n\nNo anxiety can be ours.\n\nWhat can cause you anxiety\nAnd the Spirit of the elements over you?\nNo anxiety can be ours.\n\nThe God of the elements,\nThe King of the elements,\nThe Spirit of the elements,\nClose over us,\nEver eternally.","note":"A call and response blessing of a boat: no anxiety can be ours.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg1/cg1132.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-charm-lasting-life","title":"From the Charm of the Lasting Life","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"blessing","occasion":["blessing","healing","comfort"],"text":"I place the charm on thy body,\nAnd on thy prosperity,\nThe charm of the God of life\nFor thy protection.\n\nThe host of Michael on thy side,\nThe shield of Michael on thy shoulder,\nThere is not between heaven and earth\nThat can overcome the King of grace.\n\nThe mantle of Christ Himself about thee,\nThe shadow of Christ Himself above thee,\nFrom the crown of thy head\nTo the soles of thy feet.\n\nThou shalt go forth in name of thy King,\nThou shalt come in in name of thy Chief,\nTo the God of life thou now belongest wholly,\nAnd to all the Powers together.\n\nThe charm of God about thee!\nThe arm of God above thee!","note":"A protective blessing placed on a loved one: the mantle of Christ Himself about thee.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 2, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg2/cg2016.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-virgin-and-child","title":"The Virgin and Child","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"hymn","occasion":["season","birth"],"text":"The Virgin was seen approaching,\nChrist so young on her breast,\nAngels making them obeisance,\nThe King of glory saying it is just.\n\nThe Virgin of gold-bedewed locks,\nThe Jesu whiter than snow,\nSeraphs of song singing their praise,\nThe King of glory saying it is just.","note":"A short Christmas verse of the Virgin and her Child.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 2, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg2/cg2081.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-god-of-the-moon","title":"God of the Moon","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"hymn","occasion":["season","nature","celebration"],"text":"God of the moon, God of the sun,\nGod of the globe, God of the stars,\nGod of the waters, the land, and the skies,\nWho ordained to us the King of promise.\n\nIt was Mary fair who went upon her knee,\nIt was the King of life who went upon her lap,\nDarkness and tears were set behind,\nAnd the star of guidance went up early.\n\nIllumed the land, illumed the world,\nIllumed doldrum and current,\nGrief was laid and joy was raised,\nMusic was set up with harp and pedal-harp.","note":"A Christmas hymn: God of the moon, God of the sun, and grief laid down and joy raised up.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 2, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg2/cg2082.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-mothers-consecration","title":"Mother's Consecration","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"blessing","occasion":["blessing","birth","daily"],"text":"Be the great God between thy two shoulders,\nTo protect thee in thy going and in thy coming,\nBe the Son of Mary Virgin near thine heart,\nAnd be the perfect Spirit upon thee pouring,\nOh, the perfect Spirit upon thee pouring!","note":"A blessing a mother says over a child going out from home.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 2, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg2/cg2085.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-lullaby","title":"From the Lullaby","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"song","occasion":["birth","blessing","evening"],"text":"A thousand welcomes to thee,\nHu hi! ho ho!\n\nLife and health be thine,\nHu hi! ho ho!\n\nThe age of joy be thine,\nHu hi! ho ho!\n\nIn every place,\nHu hi! ho ho!\nHu hi! hi ho!\n\nThe Mary Mother,\nHu hi! ho ho!\n\nFair white lovely,\nHu hi! ho ho!\n\nBe fondling thee,\nHu hi! ho ho!\n\nBe dandling thee,\nHu hi! ho ho!\n\nBe bathing thee,\nHu hi! ho ho!\n\nBe rearing thee,\nHu hi! ho ho!\n\nBe shielding thee\nHu hi! ho ho!\n\nFrom the net of thine enemy;\nHu hi! ho ho!\nHu hi! ho ho!\n\nBe caressing thee,\nHu hi! ho ho!\n\nBe guarding thee,\nHu hi! ho ho!\n\nBe filling thee\nHu hi! ho ho!\n\nWith the graces;\nHu hi! ho ho!\nHu hi! hi ho!\n\nThe love of thy mother, thou,\nHu hi! ho ho!\n\nThe love of her love, thou,\nHu hi! ho ho!\n\nThe love of the angels, thou,\nHu hi! ho ho!\n\nIn Paradise!\nHu hi! ho ho!\nHu hi! hi ho!","note":"A Gaelic lullaby over a little child, with its soft refrain.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 2, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg2/cg2097.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"carmina-queen-of-grace","title":"Queen of Grace","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian","catholic"],"denom":["scottish"],"type":"hymn","occasion":["comfort","hope"],"text":"Smooth her hand,\nFair her foot,\nGraceful her form,\nWinsome her voice,\nGentle her speech,\nStately her mien,\nWarm the look of her eye,\nMild the expression of her face,\nWhile her lovely white breast heaves on her bosom\nLike the black-headed sea-gull on the gently heaving wave.\n\nHoly is the virgin of gold-mist hair,\nWith tenderest babe at the base of the bens,\nNo food for either of them under the arch of the sky,\nNo shelter under the sun to shield them from the foe.\n\nThe shield of the Son of God covers her,\nThe inspiration of the Son of God guides her,\nThe word of the Son of God is food to her,\nHis star is a bright revealing light to her.\n\nThe darkness of night is to her as the brightness of day,\nThe day to her gaze is always a joy,\nWhile the Mary of grace is in every place,\nWith the seven beatitudes compassing her,\nThe seven beatitudes compassing her.","note":"A song of Mary and her Babe, sheltered by the Son of God.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 2, Alexander Carmichael (1900)","url":"https://sacred-texts.com/neu/celt/cg2/cg2099.htm"},"rights":"pd","pd":"published 1900; Carmichael died 1912"}];
